### 3. Minimal demo code

Below is a ready‑to‑copy example of a simple theme‑switching context. Copy it into a file named `ThemeContextDemo.jsx` and run it in a Create‑React‑App or Vite project.

```jsx
// ThemeContextDemo.jsx
import React, { createContext, useState, useContext } from 'react';

/* 1️⃣ Create the context */
const ThemeContext = createContext();

/* 2️⃣ Provider component */
export const ThemeProvider = ({ children }) => {
  const [theme, setTheme] = useState('light');

  const toggle = () => setTheme(prev => (prev === 'light' ? 'dark' : 'light'));

  return (
    <ThemeContext.Provider value={{ theme, toggle }}>
      {children}
    </ThemeContext.Provider>
  );
};

/* 3️⃣ Consumer hook */
export const useTheme = () => useContext(ThemeContext);

/* 4️⃣ Example component that uses the context */
export const ThemedBox = () => {
  const { theme, toggle } = useTheme();
  const style = {
    padding: '1rem',
    background: theme === 'light' ? '#fff' : '#333',
    color: theme === 'light' ? '#000' : '#fff',
    borderRadius: '4px',
    textAlign: 'center',
  };

  return (
    <div style={style}>
      <p>Current theme: {theme}</p>
      <button onClick={toggle}>Toggle Theme</button>
    </div>
  );
};

/* 5️⃣ App entry point */
export const App = () => (
  <ThemeProvider>
    <ThemedBox />
  </ThemeProvider>
);
```

**How to run:**

```bash
# If using Create React App
npx create-react-app context-demo
cd context-demo
# replace src/App.js with the code above (or import it)
npm start
```

The demo shows a button that toggles between light and dark themes, demonstrating how any component inside `ThemeProvider` can access the shared state via the `useTheme` hook.

